/** Merge verified sourceUrl onto a recipe when missing. */
export function withRecipeSource(recipe: Recipe): Recipe {
  if (recipe.sourceUrl) return recipe
  const hit = RECIPE_SOURCES[recipe.id]
  if (!hit) return recipe
  return { ...recipe, sourceUrl: hit.url, sourceName: hit.name }
}
